import sys,json,math,hashlib,copy,importlib,contextlib,io
from pathlib import Path
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'tools/geometry-textbook'))
import chapter07_common as common
raw={};old=common.Block.add
# Capture actual raw arguments without calling the author's numeric oracle as evidence.
def cap(self,*args,**kw):
 raw[args[0],args[1]]={'p':copy.deepcopy(args[5]),'cases':copy.deepcopy(kw.get('cases',[]))}
 return old(self,*args,**kw)
common.Block.add=cap;common.Block.write=lambda self:None
with contextlib.redirect_stdout(io.StringIO()):importlib.import_module('models_ch7_a')
prep=json.loads((R/'geometry-course/textbook/preparation/chapter-07-a.json').read_text())
models=json.loads((R/'geometry-course/textbook/models/chapter-07-a.json').read_text())['models']
parts={(e['number'],p['part']):p for e in prep['exercises'] for p in e['parts']}
source_parts={541:'абв',542:'абв',545:'абв',546:'абв',547:'аб',548:'абвг',549:'абв',550:'аб',555:'абвг',560:'абв',564:'абвг'}
expected_parts={(n,p) for n in range(541,566) for p in (list(source_parts[n]) if n in source_parts else ['single'])}
assert set(parts)==expected_parts
assert hashlib.sha256((R.parent/'vii-source'/'1701411644_geometrija_-uchebnik_-7-9-kl_-atanasjan_compressed.pdf').read_bytes()).hexdigest()=='3b2e890ce425ef9b4893f367e8680e18c0ed380c9bd86fe4eb65b44a2479ca72'
checks=[];coverage=set()
def eq(n,part,description,actual,expected):
 assert math.isclose(actual,expected,abs_tol=2e-7,rel_tol=2e-7),(n,part,description,actual,expected)
 checks.append(dict(number=n,part=part,check=description,actual=actual,expected=expected,passed=True));coverage.add((n,part))
def area(p,names):
 return abs(sum(p[a][0]*p[b][1]-p[a][1]*p[b][0] for a,b in zip(names,names[1:]+names[:1])))/2
D=lambda p,a,b:math.dist(p[a][:2],p[b][:2])
def ar(n,part,polygon,expected):eq(n,part,'independent shoelace area '+polygon,area(raw[n,part]['p'],polygon),expected)
for part,names in [('а','LMN'),('б','KLMN'),('в','KLMN')]:
 ar(541,part,names,12);ar(541,part,'ABC',6);ar(541,part,'DEF',6)
for part,polygon,answer in [('а','ABCD',4),('б','ABCD',4),('в','ABC',2)]:ar(542,part,polygon,answer)
for n,first,second in [(543,'ABCD','AMD'),(544,'ABCD','ADE')]:
 p=raw[n,'single']['p'];eq(n,'single','dissection total areas agree',area(p,first),area(p,second))
for a,b in [('ABE','MCE')]:
 p=raw[543,'single']['p'];eq(543,'single','equal exchanged triangle areas',area(p,a),area(p,b))
for a,b in [('ABM','EPM'),('DCN','EPN')]:
 p=raw[544,'single']['p'];eq(544,'single','equal exchanged triangle areas '+a+'/'+b,area(p,a),area(p,b))
for part,want in zip('абв',[1.44,9/16,18]):ar(545,part,'ABCD',want)
for part,want in zip('абв',[4,1.5,2*math.sqrt(3)]):eq(546,part,'square side from coordinates',D(raw[546,part]['p'],'A','B'),want)
for part,factor,answer in [('а',100,2400),('б',.01,.24)]:eq(547,part,'area in converted square units',area(raw[547,part]['p'],'ABCD')*factor,answer)
for part,want in zip('абвг',[27.2,6*math.sqrt(2),684.8,12.15]):ar(548,part,'ABCD',want)
for part,want in zip('абв',[2,4,1]):
 r=raw[549,part];eq(549,part,'case/original area ratio',area(r['cases'][0][0],'ABCD')/area(r['p'],'ABCD'),want)
ar(550,'а','ABCD',250);eq(550,'а','side ratio',D(raw[550,'а']['p'],'A','D')/D(raw[550,'а']['p'],'A','B'),2.5)
ar(550,'б','ABCD',9);eq(550,'б','perimeter',2*(D(raw[550,'б']['p'],'A','D')+D(raw[550,'б']['p'],'A','B')),12)
for n,answer in [(551,2200),(552,360)]:
 r=raw[n,'single'];eq(n,'single','room area in cm² / piece cm²',area(r['p'],'ABCD')*(10000 if n==551 else 1)/area(r['cases'][0][0],'ABCD'),answer)
 eq(n,'single','integer tiling by long and short side',600/30*550/5 if n==551 else 300/15*270/15,answer)
p=raw[553,'single'];eq(553,'single','equal rectangle and square areas',area(p['p'],'ABCD'),area(p['cases'][0][0],'ABCD'));eq(553,'single','square side',D(p['cases'][0][0],'A','B'),12)
p=raw[554,'single'];eq(554,'single','square minus rectangle area',area(p['cases'][0][0],'ABCD')-area(p['p'],'ABCD'),900)
for part,want in zip('абвг',[180,34,162,27]):ar(555,part,'ABCD',want)
for part,want in [('в',.5),('г',3)]:
 p=raw[555,part]['p'];eq(555,part,'specified height/base ratio',D(p,'B','H')/D(p,'A','D'),want)
for n,want in [(556,156),(557,84),(558,18),(559,56.7),(561,12),(562,115.52)]:ar(n,'single','ABCD',want)
for part,want,hsmall,hlarge in [('а',180,6,10),('б',60,4,6)]:
 ar(560,part,'ABCD',want);p=raw[560,part]['p'];eq(560,part,'smaller height',D(p,'D','K'),hsmall);eq(560,part,'larger height',D(p,'B','H'),hlarge)
ar(560,'в','ABCD',27);eq(560,'в','formal height to 4.5',54/4.5,12);eq(560,'в','formal height to 6',54/6,9);assert 54>4.5*6
p=raw[563,'single'];assert area(p['p'],'ABCD')<area(p['cases'][0][0],'ABCD');eq(563,'single','same side of square and rhombus',D(p['p'],'A','B'),D(p['cases'][0][0],'A','B'))
for part,want in zip('абвг',[38.5,5*math.sqrt(3),37.8,12]):ar(564,part,'ABC',want)
ar(565,'single','ABC',88);p=raw[565,'single']['p'];eq(565,'single','second altitude',D(p,'A','K'),8);eq(565,'single','given BC',D(p,'B','C'),22)
assert coverage==set(parts)==set(raw), (coverage^set(parts),coverage^set(raw))
# Independent arithmetic for every normalized declared geometric relation and displayed marker.
claims=markers=0
for entry in models:
 n,part=entry['number'],entry['part'];m=entry['model'];p=m['points']
 def vec(a,b):return [p[b][j]-p[a][j] for j in range(2)]
 def dot(u,v):return sum(a*b for a,b in zip(u,v))
 def cross(u,v):return u[0]*v[1]-u[1]*v[0]
 def angle(a,v,b):
  u,w=vec(v,a),vec(v,b);return math.degrees(math.acos(max(-1,min(1,dot(u,w)/math.sqrt(dot(u,u)*dot(w,w))))))
 for c in m['checks']:
  kind=c['type'];claims+=1
  if kind=='collinear':
   ids=c['points'];u=vec(*ids[:2]);assert all(abs(cross(u,vec(ids[0],z)))<1e-5 for z in ids[2:])
  elif kind in ['parallel','perpendicular']:
   u,v=[vec(*s) for s in c['segments']];assert abs(cross(u,v) if kind=='parallel' else dot(u,v))<1e-5,(n,c)
  elif kind=='equalLength':
   ds=[D(p,*s) for s in c['segments']];assert max(ds)-min(ds)<1e-6,(n,c)
  elif kind=='distanceRatio':
   got=D(p,*c['segments'][0])/D(p,*c['segments'][1]);assert abs(got-c['ratio'])<1e-6,(n,c,got)
  elif kind=='angle':assert abs(angle(*c['points'])-c['degrees'])<1e-6,(n,c)
  else:raise AssertionError(kind)
 for viewid,v in m['views'].items():
  for c in v.get('rightAngles',[]):assert abs(angle(c['a'],c['vertex'],c['b'])-90)<1e-6,(n,viewid,c);markers+=1
  groups={}
  for c in v.get('equalSegments',[]):groups.setdefault(c.get('marks',1),[]).append(D(p,c['a'],c['b']));markers+=1
  for ds in groups.values():assert max(ds)-min(ds)<1e-6,(n,viewid,ds)
  if viewid.startswith('case-'):assert 0<=v['availableFromStep']<=len(parts[n,part]['steps'])
 # No references to future area theorems in pre-section2 exercises; 543/544 have no hidden formula58.
 refs=[x for s in entry['didactics']['steps'] for x in s['theoryPoints']]
 assert all(1<=x<=58 for x in refs)
 if n<=554:assert max(refs)<=56,(n,refs)
 if n in [543,544]:assert 57 not in refs and 58 not in refs
 expected_page=144 if n<=543 else 145 if n<=554 else 150 if n<=560 else 151
 e=next(e for e in prep['exercises'] if e['number']==n);assert e['printedPages']==[expected_page] and e['pdfPages']==[expected_page+1]
# Parameter sweeps of both early dissection proofs, independent of author examples.
sweeps=0
for a,h in [(2,3),(9,.5),(7,6)]:
 for t in [-8,-2,0,1,9]:
  p={'A':[0,0],'B':[t,h],'C':[t+a,h],'D':[a,0],'M':[2*t+a,2*h],'E':[t+a/2,h]}
  assert abs(area(p,'ABCD')-area(p,'AMD'))<1e-9;assert abs(area(p,'ABE')-area(p,'MCE'))<1e-9;sweeps+=1
 for x in [0,.01,a/3,a/2,a-.01,a]:
  p={'A':[0,0],'B':[0,h],'C':[a,h],'D':[a,0],'E':[x,2*h],'M':[x/2,h],'N':[(x+a)/2,h],'P':[x,h]}
  assert abs(area(p,'ABCD')-area(p,'ADE'))<1e-9;assert abs(area(p,'ABM')-area(p,'EPM'))<1e-9;assert abs(area(p,'DCN')-area(p,'EPN'))<1e-9;sweeps+=1
files=['tools/geometry-textbook/models_ch7_a.py','geometry-course/textbook/preparation/chapter-07-a.json','geometry-course/textbook/models/chapter-07-a.json']
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
out={'schemaVersion':1,'reviewer':'independent author C; not author A','scope':'all 48 cards 541–565','sourceSha256':'3b2e890ce425ef9b4893f367e8680e18c0ed380c9bd86fe4eb65b44a2479ca72','reviewedFileSha256':{f:sha(R/f) for f in files},'sourceImagesActuallyViewed':{f'PDF{i}/printed{i-1}':sha((R.parent/'vii-source'/f'page-{i}.png')) for i in range(145,153)},'cardCount':len(coverage),'numericAssertions':len(checks),'coordinateClaims':claims,'rightAngleAndEqualityMarkers':markers,'earlyDissectionParameterCases':sweeps,'results':checks,'visualStatus':'pending exhaustive actual PNG review','probeSha256':sha(Path(__file__)),'probeSource':Path(__file__).read_text(),'verdict':'PASS for source/text/arithmetic/coordinate and marker scope; visual separate'}
(R/'docs/reviews/ATANASYAN_7_9_CHAPTER_VII_A_NUMERIC_REVIEW.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print({k:out[k] for k in ['cardCount','numericAssertions','coordinateClaims','rightAngleAndEqualityMarkers','earlyDissectionParameterCases']})
